mapper.select:
SELECT l.id, l.action_code, r.rule_name AS action_name, l.change_type, l.score_before, l.score_change, l.score_after, l.order_id, o.order_no, l.reason, l.create_time FROM credit_log l LEFT JOIN credit_rule r ON r.rule_type = 'ACTION' AND r.rule_code = l.action_code AND r.deleted = 0 LEFT JOIN lease_order o ON o.id = l.order_id WHERE l.user_id = #{userId}
AND l.change_type = #{changeType}
ORDER BY l.id DESC
